namespace CitationSystem.Models
{
    // All citations in a single RTE property
    public class RichTextPropertyCitations
    {
        public required Guid ElementKey { get; init; }
        public required string PropertyAlias { get; init; }
        public required string PropertyHTML { get; init; }
        public required IReadOnlyList<InTextCitation> InTextCitations { get; init; }

        // Generated by CitationNumberingService.
        // A list, in order of appearance, of the uses of each citation.
        // Used to marke the {use} portion of the citation <sup> link
        public Dictionary<Guid, List<int>> CitationOccurrences { get; } = [];
    }
}
